def fizzbuzz(n):
    """Return a list of length n. For i in 1..n: "FizzBuzz" if
    divisible by 15, "Fizz" if by 3, "Buzz" if by 5, else str(i)."""

solution:
out = []
for i in range(1, n + 1):
    if i % 15 == 0:
        out.append("FizzBuzz")
    elif i % 3 == 0:
        out.append("Fizz")
    elif i % 5 == 0:
        out.append("Buzz")
    else:
        out.append(str(i))
return out

