def flatten(nested):
    """Flatten a list that may contain nested lists (arbitrary depth)
    into a single flat list, preserving order."""

solution:
out = []
for item in nested:
    if isinstance(item, list):
        out.extend(flatten(item))
    else:
        out.append(item)
return out
